{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, count(*) c, round(avg(duration)/1e6,1) avg_ms, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND attr_span_kind='Client' AND span_name='SELECT ts.orders_other' GROUP BY 1 UNION ALL SELECT span_name, count(*), round(avg(duration)/1e6,1), round(quantile_cont(duration,0.5)/1e6,1) FROM abnormal_traces WHERE service_name='ts-order-other-service' AND attr_span_kind='Client' AND span_name='SELECT ts.orders_other' GROUP BY 1", "claim": "ts-order-other-service's SELECT ts.orders_other DB spans rose from about 0.3 ms average to about 88 ms in the incident."},
        {"kind": "trace", "sql": "SELECT 'normal' p, span_name, count(*) c, round(avg(duration)/1e6,1) avg_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('OrderOtherRepository.findAll','OrderOtherRepository.findByAccountId') GROUP BY 1,2 UNION ALL SELECT 'abnormal', span_name, count(*), round(avg(duration)/1e6,1) FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('OrderOtherRepository.findAll','OrderOtherRepository.findByAccountId') GROUP BY 1,2", "claim": "Repository methods in ts-order-other-service slowed from about 2 ms to hundreds of ms, consistent with slow DB calls, while its CPU stayed flat or lower."},
        {"kind": "metric", "sql": "SELECT 'normal' p, round(avg(value),3) avg_cpu FROM normal_metrics WHERE service_name='ts-order-other-service' AND metric='container.cpu.usage' UNION ALL SELECT 'abnormal', round(avg(value),3) FROM abnormal_metrics WHERE service_name='ts-order-other-service' AND metric='container.cpu.usage'", "claim": "ts-order-other-service container CPU usage did not rise during the incident, so the slowdown is not CPU saturation."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-order-other-service", "to": "ts-seat-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name cs, s.service_name ss, count(*) cnt, round(avg(c.duration)/1e6,1) cavg_ms, round(avg(s.duration)/1e6,1) savg_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-seat-service' AND s.service_name='ts-order-other-service' GROUP BY 1,2", "claim": "Seat's calls to ts-order-other-service rose from about 2 ms to about 51 ms server time in the incident."}]},
    {"from": "ts-seat-service", "to": "ts-travel2-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name cs, s.service_name ss, count(*) cnt, round(avg(c.duration)/1e6,1) cavg_ms, round(avg(s.duration)/1e6,1) savg_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-travel2-service' AND s.service_name='ts-seat-service' GROUP BY 1,2", "claim": "travel2's calls to seat rose from about 9.6 ms to about 80 ms client time during the incident."}]},
    {"from": "ts-order-other-service", "to": "ts-admin-order-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name cs, s.service_name ss, count(*) cnt, round(avg(c.duration)/1e6,1) cavg_ms, round(avg(s.duration)/1e6,1) savg_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-admin-order-service' AND s.service_name='ts-order-other-service' GROUP BY 1,2", "claim": "admin-order's calls to ts-order-other-service rose from about 5 ms to about 582 ms in the incident."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name cs, s.service_name ss, count(*) cnt, round(avg(c.duration)/1e6,1) cavg_ms, round(avg(s.duration)/1e6,1) savg_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='loadgenerator' AND s.service_name='ts-ui-dashboard' GROUP BY 1,2", "claim": "User requests through ts-ui-dashboard slowed from about 21.7 ms to about 32 ms during the incident."}]},
    {"from": "ts-admin-order-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) c, round(avg(duration)/1e6,1) avg_ms, sum(CASE WHEN attr_http_response_status_code>=400 THEN 1 ELSE 0 END) http_errors FROM abnormal_traces WHERE service_name='ts-admin-order-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "ts-admin-order-service server spans slowed from about 12 ms to 300+ ms, with 4xx errors on POST and DELETE."}]}
  ]
}
